pub(super) fn product_grade__real_data_validation(mut repo_root: Value) -> Result<Value> {
    let mut path: Value;
    let mut residual_blockers: Value;
    let mut text: Value;
    path = join_path(
        &join_path(&join_path(&repo_root, &json!("docs")), &json!("acceptance")),
        &json!("REAL_REPO_BULK_VALIDATION_20260702.md"),
    );
    if !(truth(&json!(to_path(&path).exists()))) {
        return Ok(Value::Object(
            [
                ("present".into(), json!(false)),
                ("repo_suite_count".into(), json!(0)),
                ("executed_records".into(), json!(0)),
                ("qeg_smoke_passed".into(), json!(false)),
                (
                    "residual_blockers".into(),
                    Value::Array(vec![json!("real repo validation record missing")]),
                ),
                ("sourceRef".into(), json!(values::text(&path))),
            ]
            .into_iter()
            .collect(),
        ));
    }
    text = json!(std::fs::read_to_string(to_path(&path))?);
    residual_blockers = Value::Array(vec![]);
    if (contains(&text, &json!("memx-resolver"))) && (contains(&text, &json!("missing `yaml`"))) {
        {
            let incoming = json!("memx-resolver dependency setup remains unstable");
            edit(&mut residual_blockers, "append", incoming)?;
        }
    }
    if (contains(&text, &json!("`uv` cache access problem")))
        || (contains(&text, &json!("uv cache")))
    {
        {
            let incoming = json!("uv cache permission friction remains in combined/sandboxed runs");
            edit(&mut residual_blockers, "append", incoming)?;
        }
    }
    if (contains(&text, &json!("total_checks"))) && (contains(&text, &json!("total_tests"))) {
        {
            let incoming =
                json!("build/typecheck records must stay out of executable test-oracle scoring");
            edit(&mut residual_blockers, "append", incoming)?;
        }
    }
    return Ok(Value::Object(
        [
            ("present".into(), json!(true)),
            (
                "repo_suite_count".into(),
                (if contains(&text, &json!("22 repo/suites")) {
                    json!(22)
                } else {
                    json!(0)
                }),
            ),
            (
                "executed_records".into(),
                (if contains(&text, &json!("12,771")) {
                    json!(12771)
                } else {
                    json!(0)
                }),
            ),
            (
                "qeg_smoke_passed".into(),
                json!(contains(
                    &text,
                    &json!("QEG `build`, `validate`, `gate`, and `record` passed")
                )),
            ),
            ("residual_blockers".into(), residual_blockers.clone()),
            ("sourceRef".into(), json!(values::text(&path))),
        ]
        .into_iter()
        .collect(),
    ));
}

